public class Track {public string Id{get;set;} public string File{get;set;} public string Title{get;set;} public string Art{get;set;} public string Link{get;set;} public string Upload{get;set;} public override string ToString(){return Title+"   ·   "+Path.GetExtension(File).TrimStart('.').ToUpperInvariant()+"   ·   "+(Upload??"Not uploaded");}}
public class Release {public string Title{get;set;} public string Date{get;set;} public string Notes{get;set;} public bool Master{get;set;} public bool Artwork{get;set;} public bool Metadata{get;set;} public bool Published{get;set;} public override string ToString(){return Title+"   ·   "+Date;}}
