public static class Program {
 static Mutex mutex;static EventWaitHandle activate;
 [STAThread]public static int Main(string[] args){
  bool first;mutex=new Mutex(true,"Local\\SoundcloudDesktop.Native.SingleInstance",out first);
  if(!first){try{EventWaitHandle.OpenExisting("Local\\SoundcloudDesktop.Native.Activate").Set();}catch{}return 0;}
  activate=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\SoundcloudDesktop.Native.Activate");
  try{
   Transport.Verify();
   if(args.Length>0&&args[0]=="--verify-transport"){if(Convert.ToInt32(Transport.Request("https://api.soundcloud.com/me",null,null,null,false)["_http"])!=401)return 1;return 0;}
   if(args.Length>0&&args[0]=="--self-test"){SelfTest.Run();return 0;}
   Application app=new Application();Shell shell=new Shell();
   ThreadPool.QueueUserWorkItem(delegate{while(activate.WaitOne()){app.Dispatcher.BeginInvoke(new Action(delegate{shell.Window.Show();if(shell.Window.WindowState==WindowState.Minimized)shell.Window.WindowState=WindowState.Normal;shell.Window.Activate();}));}});
   app.DispatcherUnhandledException+=delegate(object s,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){shell.Notify("The action could not finish. Your saved workspace is preserved. "+e.Exception.Message);e.Handled=true;};
   app.Run(shell.Window);return 0;
  }catch(Exception e){if(args.Length>0)return 1;MessageBox.Show(e.Message,"Soundcloud Desktop",MessageBoxButton.OK,MessageBoxImage.Error);return 1;}
  finally{activate.Close();mutex.ReleaseMutex();mutex.Close();}
 }
}

