 void Upload(){if(selected==null)throw new Exception("Choose your audio file first.");if(!verifiedAccount){Page("Account");Notify("Connect and verify your artist account before uploading.");return;}if(Text("TrackTitle")=="")throw new Exception("Enter a track title.");Track track=selected;string sharing=Get<ComboBox>("VisibilityChoice").SelectedIndex==1?"public":"private";if(track.Upload!=null&&MessageBox.Show("This file was uploaded before. Upload a separate copy?","Duplicate upload",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;
 var fields=new Dictionary<string,string>{{"title",Text("TrackTitle")},{"artist",Text("Artist")},{"genre",Text("Genre")},{"description",Text("Description")},{"sharing",sharing}};track.Title=fields["title"];Save();Get<ProgressBar>("TransferProgress").Value=0;Get<ProgressBar>("TransferProgress").IsIndeterminate=true;Get<Button>("CancelUpload").Visibility=System.Windows.Visibility.Visible;Get<TextBlock>("UploadHint").Text="Connecting securely to SoundCloud…";Transport.Progress=delegate(int p){Window.Dispatcher.BeginInvoke(new Action(delegate{Get<ProgressBar>("TransferProgress").IsIndeterminate=false;Get<ProgressBar>("TransferProgress").Value=p;Get<TextBlock>("UploadHint").Text=p+"% transferred · Keep the app running";}));};Dictionary<string,object> result=null;
 Work(delegate{VerifyAccount();result=Transport.Request("https://api.soundcloud.com/tracks",account.Access,fields,track.File,true,track.Art);if(!result.ContainsKey("id")&&!result.ContainsKey("urn"))throw new Exception("No track identifier returned. Check your catalog before retrying.");},delegate{track.Link=Value(result,"permalink_url");track.Upload=sharing+" · "+DateTime.Now.ToString("g");Save();Refresh();Get<ProgressBar>("TransferProgress").Value=100;Get<TextBlock>("UploadHint").Text="Upload accepted. SoundCloud may still be processing the audio.";Notify("Uploaded "+track.Title+" as "+sharing+". "+track.Link);});
 }
 void StartAuth(){if(busy||authPending)throw new Exception("An operation is already running.");if(String.IsNullOrEmpty(account.ClientId)||String.IsNullOrEmpty(account.Secret))throw new Exception("Save your registered app credentials first.");verifier=Random();authState=Random();authStarted=DateTime.UtcNow;authClaimed=0;string challenge;using(var sha=SHA256.Create())challenge=B64(sha.ComputeHash(Encoding.ASCII.GetBytes(verifier)));authUrl="https://secure.soundcloud.com/authorize?client_id="+Uri.EscapeDataString(account.ClientId)+"&redirect_uri="+Uri.EscapeDataString("http://127.0.0.1:49832/callback")+"&response_type=code&code_challenge_method=S256&code_challenge="+challenge+"&state="+authState;listener=new TcpListener(IPAddress.Loopback,49832);listener.Start();authPending=true;TcpListener active=listener;
 ThreadPool.QueueUserWorkItem(delegate{while(authPending){try{if(DateTime.UtcNow-authStarted>TimeSpan.FromMinutes(5)){Window.Dispatcher.BeginInvoke(new Action(delegate{listenerStop();Notify("Authorization expired. Connect again to start a new request.");}));break;}if(!active.Pending()){Thread.Sleep(150);continue;}using(TcpClient client=active.AcceptTcpClient()){client.ReceiveTimeout=5000;using(NetworkStream stream=client.GetStream()){StreamReader reader=new StreamReader(stream);string line=reader.ReadLine();if(line==null||line.Length>8192)continue;string[] parts=line.Split(' ');if(parts.Length<2)continue;string callback="http://127.0.0.1:49832"+parts[1];string message="Return to Soundcloud Desktop to finish connecting.";byte[] body=Encoding.UTF8.GetBytes(message);byte[] header=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(body,0,body.Length);Window.Dispatcher.BeginInvoke(new Action(delegate{try{CompleteCallback(callback);}catch(Exception e){Notify(e.Message);}}));}}}catch{if(!authPending)break;}}});Open(authUrl);Notify("Approve access in your browser. You can also copy the authorization link to another device.");}
 void CompleteCallback(string address){if(!authPending||DateTime.UtcNow-authStarted>TimeSpan.FromMinutes(5))throw new Exception("Start a new connection attempt first.");Uri u;if(!Uri.TryCreate(address,UriKind.Absolute,out u)||u.Host!="127.0.0.1"||u.Port!=49832||u.AbsolutePath!="/callback")throw new Exception("Paste the full redirect address from the authorization browser.");var q=HttpUtility.ParseQueryString(u.Query);if(q["state"]!=authState)throw new Exception("Authorization state did not match. Use the current connection attempt.");if(String.IsNullOrEmpty(q["code"]))throw new Exception("Authorization was not approved.");if(Interlocked.Exchange(ref authClaimed,1)!=0)return;string code=q["code"];listenerStop();Box("CallbackAddress").Clear();Work(delegate{Exchange(new Dictionary<string,string>{{"grant_type","authorization_code"},{"code",code},{"code_verifier",verifier},{"redirect_uri","http://127.0.0.1:49832/callback"}});VerifyAccount();},delegate{Refresh();Page("Upload");Notify("Connected as "+account.User+". You can upload your music now.");});}
 void listenerStop(){authPending=false;if(listener!=null){listener.Stop();listener=null;}}
 void VerifyAccount(){verifiedAccount=false;EnsureToken();var profile=Transport.Request("https://api.soundcloud.com/me",account.Access,null,null,true);if(!profile.ContainsKey("id")&&!profile.ContainsKey("urn"))throw new Exception("SoundCloud did not return a verified account ID. Reconnect before uploading.");account.User=Value(profile,"username");SaveAccount();verifiedAccount=true;}
 void EnsureToken(){lock(accountLock){if(String.IsNullOrEmpty(account.Access))throw new Exception("Connect your account first.");if(DateTime.UtcNow.Ticks>account.Expires-TimeSpan.FromMinutes(1).Ticks)Exchange(new Dictionary<string,string>{{"grant_type","refresh_token"},{"refresh_token",account.Refresh}});}}
 void Exchange(Dictionary<string,string> fields){fields["client_id"]=account.ClientId;fields["client_secret"]=account.Secret;var result=Transport.Request("https://secure.soundcloud.com/oauth/token",null,fields,null,true);string access=Value(result,"access_token"),refresh=Value(result,"refresh_token");if(access==""||refresh=="")throw new Exception("SoundCloud did not return complete credentials.");account.Access=access;account.Refresh=refresh;account.Expires=DateTime.UtcNow.AddSeconds(result.ContainsKey("expires_in")?Convert.ToDouble(result["expires_in"]):3600).Ticks;SaveAccount();}
 void SaveAccount(){byte[] bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(Serialize(account)),null,DataProtectionScope.CurrentUser);Atomic(secretFile,bytes);}
 void Save(){Validate(data);Atomic(workspaceFile,Encoding.UTF8.GetBytes(Serialize(data)));}
 public static void Atomic(string path,byte[] bytes){string temp=path+".tmp";File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 public static void Validate(Workspace w){if(w==null||w.Version!=1||w.Tracks==null||w.Releases==null||w.Campaigns==null||w.Tracks.Any(t=>t==null||String.IsNullOrEmpty(t.Id)||String.IsNullOrEmpty(t.File)||t.Title==null)||w.Tracks.Select(t=>t.Id).Distinct().Count()!=w.Tracks.Count||w.Releases.Any(r=>r==null||r.Title==null)||w.Campaigns.Any(c=>c==null||c.Title==null))throw new Exception("The workspace is invalid. The existing saved data has been preserved.");}
 public static string Serialize(object o){return new JavaScriptSerializer{MaxJsonLength=16000000}.Serialize(o);}public static T Deserialize<T>(string s){return new JavaScriptSerializer{MaxJsonLength=16000000}.Deserialize<T>(s);}public static string Value(Dictionary<string,object>d,string k){return d.ContainsKey(k)&&d[k]!=null?Convert.ToString(d[k]):"";}
 static string B64(byte[] b){return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}static string Random(){byte[] b=new byte[32];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return B64(b);}static void Open(string url){Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
}
public static class SelfTest {
 public static void Run(){string temp=Path.Combine(Path.GetTempPath(),"scd-native-test-"+Guid.NewGuid());Directory.CreateDirectory(temp);Workspace w=new Workspace();w.Tracks.Add(new Track{Id="1",Title="Native test",File=Path.Combine(temp,"track.wav")});w.Releases.Add(new Release{Title="Test release",Master=true});Shell.Validate(w);string file=Path.Combine(temp,"workspace.json");Shell.Atomic(file,Encoding.UTF8.GetBytes(Shell.Serialize(w)));w.Campaigns.Add(new Campaign{Title="Test campaign",Text="Caption"});Shell.Atomic(file,Encoding.UTF8.GetBytes(Shell.Serialize(w)));var read=Shell.Deserialize<Workspace>(File.ReadAllText(file));if(read.Tracks.Count!=1||!read.Releases[0].Master||read.Campaigns.Count!=1)throw new Exception("Persistence test failed.");byte[] input=Encoding.UTF8.GetBytes("test-only-secret");byte[] encrypted=ProtectedData.Protect(input,null,DataProtectionScope.CurrentUser);if(!input.SequenceEqual(ProtectedData.Unprotect(encrypted,null,DataProtectionScope.CurrentUser)))throw new Exception("Credential test failed.");using(Stream s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("App.xaml")){Window win=(Window)XamlReader.Load(s);if(win.FindName("UploadButton")==null)throw new Exception("UI test failed.");}File.WriteAllText(Path.Combine(Transport.Root,"self-test-result.txt"),"PASS: native UI loads; metadata save/reload; credential encryption; transport SHA-256 validation. "+DateTime.UtcNow.ToString("o"));}
}
